import { createContext, useContext } from 'react';
import { cx } from './cx';

/** Per-slot class names, e.g. `{ root: 'my-switch', bulb: 'my-bulb' }`. */
export type ClassNames<Slot extends string> = Partial<Record<Slot, string>>;

export interface ComponentConfig<P = Record<string, unknown>> {
  /** Props applied when the component doesn't set them itself. */
  defaultProps?: Partial<P>;
  /** Extra class names for named parts. `root` is the outer element. */
  classNames?: Record<string, string>;
}

export type DefaultsMap = Record<string, ComponentConfig | undefined>;

export const DefaultsContext = createContext<DefaultsMap>({});

/**
 * Merge app-wide defaults (from SparkProvider) under a component's own props.
 * Props passed directly always win; class names from both sources are joined.
 */
export function useDefaults<P extends object>(name: string, props: P): P {
  const config = useContext(DefaultsContext)[name];
  if (!config) return props;
  const merged: Record<string, unknown> = { ...config.defaultProps };
  for (const [k, v] of Object.entries(props)) if (v !== undefined) merged[k] = v;

  const own = (props as { classNames?: Record<string, string> }).classNames;
  if (config.classNames || own) {
    const keys = new Set([...Object.keys(config.classNames ?? {}), ...Object.keys(own ?? {})]);
    const joined: Record<string, string> = {};
    keys.forEach((k) => (joined[k] = cx(config.classNames?.[k], own?.[k])));
    merged.classNames = joined;
  }
  return merged as P;
}

/** Class for one part: the base class, then app-wide and per-instance additions. */
export const slot = <S extends string>(base: string, classNames: ClassNames<S> | undefined, name: S, ...extra: Array<string | false | null | undefined>) =>
  cx(base, classNames?.[name], ...extra);

/**
 * The energy dial. One attribute, `data-spark-energy`, sets how lively the
 * whole UI is; CSS reads it for flow speed and glow, and these helpers read
 * it for spark bursts and haptics. It is read from the DOM at the moment of
 * use, so it works from SparkProvider, from a plain `<html data-spark-energy>`
 * (server-rendered, no JS), and inside portals that copy the attribute.
 */
export type Energy = 'off' | 'calm' | 'default' | 'electric';

/** How much of each effect a level keeps: particle count, spread, haptic strength. */
export const ENERGY_SCALE: Record<Energy, number> = { off: 0, calm: 0.4, default: 1, electric: 1.8 };

export function prefersReducedMotion() {
  return typeof window !== 'undefined' && typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

/** Energy in effect at an element. Reduced motion always means `off`. */
export function readEnergy(el?: Element | null): Energy {
  if (prefersReducedMotion()) return 'off';
  const host = (el ?? (typeof document !== 'undefined' ? document.documentElement : null))?.closest?.('[data-spark-energy]');
  const v = host?.getAttribute('data-spark-energy');
  return v === 'off' || v === 'calm' || v === 'electric' ? v : 'default';
}

export type HapticKind = 'toggle' | 'burst' | 'error';

/**
 * A short vibration where the browser supports it (mostly Android), only
 * when haptics are switched on (`data-spark-haptics="on"`, set by
 * `SparkProvider haptics`) and energy isn't `off`. Silent everywhere else.
 */
export function haptic(kind: HapticKind = 'toggle', el?: Element | null) {
  if (typeof navigator === 'undefined' || typeof navigator.vibrate !== 'function') return false;
  const host = (el ?? document.documentElement)?.closest?.('[data-spark-haptics]');
  if (host?.getAttribute('data-spark-haptics') !== 'on') return false;
  const scale = ENERGY_SCALE[readEnergy(el)];
  if (!scale) return false;
  const ms = (n: number) => Math.max(4, Math.round(n * Math.min(scale, 1.5)));
  const pattern = kind === 'toggle' ? ms(10) : kind === 'burst' ? [ms(8), 28, ms(8)] : [ms(30), 40, ms(30)];
  try {
    return navigator.vibrate(pattern);
  } catch {
    return false;
  }
}

/**
 * Plays the power-cut flicker on any element (the effect Modal's backdrop
 * uses). Resolves when it ends; does nothing when energy is `off`.
 */
export function powerCut(el: HTMLElement | null): Promise<void> {
  if (!el || readEnergy(el) === 'off' || typeof el.animate !== 'function') return Promise.resolve();
  const calm = readEnergy(el) === 'calm';
  const frames: Keyframe[] = calm
    ? [{ opacity: 0.6 }, { opacity: 1 }]
    : [{ opacity: 1 }, { opacity: 0.2, offset: 0.12 }, { opacity: 0.9, offset: 0.24 }, { opacity: 0.1, offset: 0.36 }, { opacity: 1, offset: 0.6 }, { opacity: 1 }];
  const anim = el.animate(frames, { duration: calm ? 200 : 420, easing: 'linear' });
  return anim.finished.then(
    () => undefined,
    () => undefined,
  );
}

import { useEffect, useLayoutEffect } from 'react';

/** useLayoutEffect in the browser, useEffect on the server (no SSR warning). */
export const useIsoLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

import React, { useRef, useState } from 'react';
import { useIsoLayoutEffect } from './useIsoLayoutEffect';

/**
 * Portals render into document.body, outside any `[data-spark-theme]` wrapper.
 * Put `anchorRef` on an element in the normal tree (or pass `sourceRef`, e.g.
 * the trigger); spread `themeProps` on the portal's root so it gets the same
 * mode and token overrides.
 */
export function usePortalTheme(active: boolean, sourceRef?: React.RefObject<Element | null>) {
  const anchorRef = useRef<HTMLSpanElement>(null);
  const [themeProps, setThemeProps] = useState<{ 'data-spark-theme'?: string; 'data-spark-energy'?: string; 'data-spark-haptics'?: string; style?: React.CSSProperties }>({});

  useIsoLayoutEffect(() => {
    if (!active) return;
    const host = (sourceRef?.current ?? anchorRef.current)?.closest<HTMLElement>('[data-spark-theme]');
    if (!host) return;
    const style: Record<string, string> = {};
    for (let i = 0; i < host.style.length; i++) {
      const name = host.style[i];
      if (name.startsWith('--')) style[name] = host.style.getPropertyValue(name);
    }
    // The energy dial and haptics travel with the theme into the portal.
    const from = sourceRef?.current ?? anchorRef.current;
    const energy = from?.closest('[data-spark-energy]')?.getAttribute('data-spark-energy') ?? undefined;
    const haptics = from?.closest('[data-spark-haptics]')?.getAttribute('data-spark-haptics') ?? undefined;
    setThemeProps({ 'data-spark-theme': host.getAttribute('data-spark-theme') ?? undefined, 'data-spark-energy': energy, 'data-spark-haptics': haptics, style: style as React.CSSProperties });
  }, [active]);

  return { anchorRef, themeProps };
}

import type { ComponentPropsWithRef, ElementType } from 'react';

/** True when the user asked the OS to reduce motion. */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || !window.matchMedia) return false;
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

/** Props of a polymorphic component rendered as `C`. */
export type OverrideProps<
  M extends { props: object; defaultComponent: ElementType },
  C extends ElementType,
> = M['props'] & Omit<ComponentPropsWithRef<C>, keyof M['props']>;
